    @Test
    fun `matches the reference encoder module for module`() {
        for (case in cases) {
            val qr = QrCode.encode(case.text, forceMask = case.mask)
            assertEquals("version for ${case.text.take(40)}", case.version, qr.version)
            assertEquals(case.rows.size, qr.size)
            for (y in 0 until qr.size) {
                val row = (0 until qr.size).joinToString("") { if (qr.isDark(it, y)) "1" else "0" }
                assertEquals("row $y of ${case.text.take(40)} (v${case.version}, mask ${case.mask})", case.rows[y], row)
            }
        }
    }

    @Test
    fun `automatic mask choice yields a valid symbol of the same version`() {
        for (case in cases) {
            val qr = QrCode.encode(case.text)
            assertEquals(case.version, qr.version)
            assertTrue(qr.mask in 0..7)
            // Finder pattern corners are mask-independent.
            assertTrue(qr.isDark(0, 0) && qr.isDark(qr.size - 1, 0) && qr.isDark(0, qr.size - 1))
        }
    }

    @Test
    fun `text beyond version 10 is rejected`() {
        try {
            QrCode.encode("x".repeat(214))
            fail("expected rejection")
        } catch (_: IllegalArgumentException) {
            // expected
        }
        assertEquals(10, QrCode.encode("x".repeat(213)).version)
    }
